<?php if($error): ?><div class="alert error" role="alert"><?= vehicleEscape($error) ?></div><?php endif; ?><?php if($flash): ?><div class="alert success" role="status"><?= vehicleEscape($flash['message']) ?></div><?php endif; ?>
<section class="service-panel"><div class="service-request-heading"><div><h2><?= $isResident?'Your vehicle registry':'Vehicle registration reviews' ?></h2><p><?= $isResident ? (residentHasPermission('resident.stickers.order') ? 'Register your resident vehicle and upload its OR/CR. Order one sticker per approved vehicle. Visitor vehicles use temporary parking passes.' : 'Register your own vehicle and upload its OR/CR for management review. Paid parking stickers and their billing are managed by the unit owner.') : 'Review ownership documents here. Paid parking stickers are issued from Parking & Stickers and linked to approved vehicles.' ?></p></div><?php if (!$isResident || residentHasPermission('resident.stickers.order')): ?><a class="service-btn service-btn-secondary" href="<?= $isResident ? 'parking.php#residentSticker' : 'parking.php?tab=stickers' ?>"><?= systemSidebarIcon('parking') ?> Parking &amp; Stickers</a><?php elseif (residentHasPermission('resident.parking.request')): ?><a class="service-btn service-btn-secondary" href="parking.php#visitorParking"><?= systemSidebarIcon('parking') ?> Visitor Parking</a><?php endif; ?></div>
<?php if($isResident): ?><form method="post" action="vehicles.php" enctype="multipart/form-data" class="service-form"><?= workflowCsrfField() ?><input type="hidden" name="action" value="register_vehicle">
<?php foreach(['make'=>'Make','model'=>'Model','color'=>'Color','plate_number'=>'Plate number'] as $name=>$label): ?><label class="field-label" for="vehicle_<?= $name ?>"><?= $label ?><input id="vehicle_<?= $name ?>" name="<?= $name ?>" value="<?= vehicleValue($name) ?>" maxlength="<?= ['make'=>80,'model'=>100,'color'=>50,'plate_number'=>20][$name] ?>" required></label><?php endforeach; ?>
<label class="field-label" for="vehicle_year">Year<input id="vehicle_year" name="year" type="number" min="1900" max="<?= (int)date('Y')+1 ?>" value="<?= vehicleValue('year') ?>" required></label><label class="field-label" for="vehicle_or_cr">OR/CR · PDF, JPG or PNG · max 5 MB<input id="vehicle_or_cr" name="or_cr" type="file" accept="application/pdf,image/jpeg,image/png" required></label><label class="field-label service-wide" for="vehicle_photo">Vehicle photo (optional) · JPG or PNG · max 5 MB<input id="vehicle_photo" name="vehicle_photo" type="file" accept="image/jpeg,image/png"></label><div class="service-submit service-wide"><button class="service-btn" type="submit">Submit vehicle for review</button></div></form><?php endif; ?></section>
<section class="service-panel"><h2><?= $isResident?'Your vehicles':'Registered vehicles' ?></h2><?php if(!$isResident): ?><p>Archived residents' vehicles are excluded from this list. Their registrations and documents remain in the account's Registered Vehicle History<?php if(canAccess('archive.manage')): ?> in <a href="archive.php">Archive</a><?php endif; ?>.</p><?php endif; ?><?php if(!$isResident && ($parkingWorkspaceEmbedded ?? false)) renderParkingListSearch('vehicles', 'Search registered vehicles', 'Resident, unit, plate, make, model, sticker or slot'); ?><?php if(!$vehicles): ?><p>No registered vehicles yet.</p><?php endif; ?><div class="vehicle-card-grid" id="parking-search-list-vehicles">
<?php foreach($vehicles as $vehicle): $vehicleState=vehicleRegistryStatus($vehicle); $sticker=$stickers[(int)$vehicle['id']]??null; ?><article class="vehicle-card" id="vehicle-<?= (int)$vehicle['id'] ?>"<?php if(!$isResident): ?> data-parking-search-item="vehicles" data-parking-search-text="<?= vehicleEscape(implode(' ', [$vehicle['full_name'], $vehicle['unit_number'] ?? '', $vehicle['plate_number'], $vehicle['year'], $vehicle['make'], $vehicle['model'], $vehicle['color'], $vehicleState['label'], $sticker['sticker_number'] ?? '', $vehicleSlotLabels[(int)($vehicle['parking_slot_id'] ?? 0)] ?? 'Not assigned'])) ?>"<?php endif; ?>><div class="service-request-heading"><h3><?= vehicleEscape($vehicle['plate_number']) ?></h3><span class="badge unit-status <?= vehicleEscape($vehicleState['class']) ?>"><?= vehicleEscape($vehicleState['label']) ?></span></div><p><?= vehicleEscape($vehicle['year'].' '.$vehicle['make'].' '.$vehicle['model'].' · '.$vehicle['color']) ?></p><?php if(!$isResident): ?><p><?= vehicleEscape($vehicle['full_name']) ?> · Unit <?= vehicleEscape($vehicle['unit_number']) ?></p><?php endif; ?>
<?php if($vehicle['rejection_reason']): ?><p>Review note: <?= vehicleEscape($vehicle['rejection_reason']) ?></p><?php endif; ?>
<p>Sticker: <strong><?= $isResident && !residentHasPermission('resident.stickers.order') ? 'Managed by the unit owner' : ($sticker?($sticker['sticker_number']?vehicleEscape($sticker['sticker_number']):($sticker['payment_status']==='paid'?'Paid · awaiting issuance':'Awaiting payment')):($vehicle['status']==='approved'?'Ready to request':'Available after vehicle approval')) ?></strong></p>
<p>Parking slot: <strong><?= vehicleEscape($vehicleSlotLabels[(int)($vehicle['parking_slot_id'] ?? 0)] ?? 'Not assigned') ?></strong></p>
<?php if(!$isResident && $vehicleState['actionable'] && canAccess('stickers.issue') && $vehicle['status']==='approved' && $sticker && $sticker['claim_status']==='issued' && $sticker['payment_status']==='paid' && $sticker['order_status']!=='cancelled' && $sticker['sticker_revoked_at']===null && $sticker['order_revoked_at']===null): ?>
<form method="post" action="parking.php?tab=vehicles" class="parking-request-decide vehicle-slot-form"><?= workflowCsrfField() ?>
    <input type="hidden" name="action" value="reassign_vehicle_slot">
    <input type="hidden" name="vehicle_id" value="<?= (int)$vehicle['id'] ?>">
    <select name="slot_id" required aria-label="Choose a resident slot for <?= vehicleEscape($vehicle['plate_number']) ?>"<?= !$vehicleAssignableSlots?' disabled':'' ?>>
        <option value=""><?= $vehicleAssignableSlots?'Choose a resident slot':'No resident slots available' ?></option>
        <?php foreach($vehicleAssignableSlots as $slot): ?><option value="<?= (int)$slot['id'] ?>"><?= vehicleEscape($slot['slot_code'].' - '.$slot['level']) ?></option><?php endforeach; ?>
    </select>
    <button type="submit" class="service-btn"<?= !$vehicleAssignableSlots?' disabled':'' ?>>Save slot</button>
</form>
<?php endif; ?>
<div class="service-actions"><?php if($isResident || canReviewPermits()): ?><a class="service-btn service-btn-secondary" href="../vehicle_document.php?vehicle_id=<?= (int)$vehicle['id'] ?>&amp;document=or_cr" target="_blank" rel="noopener">View OR/CR</a><?php if($vehicle['vehicle_photo_path']): ?><a class="service-btn service-btn-secondary" href="../vehicle_document.php?vehicle_id=<?= (int)$vehicle['id'] ?>&amp;document=photo" target="_blank" rel="noopener">View photo</a><?php endif; ?><?php endif; ?>
<?php if($isResident && residentHasPermission('resident.stickers.order') && $vehicle['status']==='approved' && !$sticker): ?><a class="service-btn" href="parking.php?vehicle_id=<?= (int)$vehicle['id'] ?>#residentSticker">Request sticker</a><?php endif; ?></div>
<?php if(!$isResident && $vehicleState['actionable'] && canReviewPermits() && $vehicle['status']==='pending'): ?><form method="post" action="registeredvehicles.php" class="service-actions"><?= workflowCsrfField() ?><input type="hidden" name="action" value="review_vehicle"><input type="hidden" name="vehicle_id" value="<?= (int)$vehicle['id'] ?>"><input name="review_notes" maxlength="255" aria-label="Review note" placeholder="Reason required for rejection"><button class="service-btn service-btn-approve" name="decision" value="approved">Approve vehicle</button><button class="service-btn service-btn-danger" name="decision" value="rejected">Reject vehicle</button></form><?php endif; ?></article><?php endforeach; ?></div></section>
